          "sampleSolution": "public class Cala {\n    private String owner;\n    private int price;\n\n    public Cala() {\n    }\n\n    public Cala(String owner, int price) {\n        this.owner = owner;\n        this.price = price;\n    }\n\n    public String getOwner() {\n        return owner;\n    }\n\n    public int getPrice() {\n        return price;\n    }\n\n    public void setOwner(String owner) {\n        this.owner = owner;\n    }\n\n    @Override\n    public String toString() {\n        return owner + \", \" + price;\n    }\n}\n\npublic class SpecCala extends Cala {\n    private int color;\n\n    public SpecCala() {\n    }\n\n    public SpecCala(int color, String owner, int price) {\n        super(owner, price);\n        this.color = color;\n    }\n\n    @Override\n    public String toString() {\n        return getOwner() + \", \" + getPrice() + \", \" + color;\n    }\n\n    public void setData() {\n        String owner = getOwner();\n        setOwner(owner.charAt(0) + \"XX\" + owner.substring(2));\n    }\n\n    public int getValue() {\n        return (color % 2 != 0) ? getPrice() + 3 : getPrice() + 7;\n    }\n}",
